#!/bin/bash
# ============================================================================
# install_selection.sh -- adds the controls + selective-regeneration stages, and
# makes Stage 1 resumable/shardable so the 1,000-document run can survive a
# SLURM time limit.
#
# Run from the repo root on Bender:   bash install_selection.sh
#
# Everything it overwrites is backed up to <file>.bak.<timestamp> first, and
# every file is sha256-verified after writing. Safe to re-run.
# ============================================================================
set -euo pipefail

if [ ! -d scripts ] || [ ! -d src/probe_extraction ]; then
  echo "FATAL: run this from the NLP_Lab repo root (no scripts/ or src/ here)."
  exit 1
fi

TS=$(date +%Y%m%d-%H%M%S)
mkdir -p scripts src/probe_extraction/utils tests configs docs

write_file() {   # write_file <path> <sha256> <<< base64
  local path="$1" want="$2" b64 got cur
  b64=$(cat)
  if [ -f "$path" ]; then
    cur=$(sha256sum "$path" | cut -d' ' -f1)
    # Most installer runs rewrite identical bytes. Skipping those avoids a
    # backup file per run per file, which is where the .bak clutter came from.
    if [ "$cur" = "$want" ]; then
      echo "  ok  $path (unchanged)"
      return 0
    fi
    cp -p "$path" "${path}.bak.${TS}"
    echo "  backed up -> ${path}.bak.${TS}"
  fi
  printf '%s' "$b64" | base64 -d > "$path"
  got=$(sha256sum "$path" | cut -d' ' -f1)
  if [ "$got" != "$want" ]; then
    echo "FATAL: checksum mismatch for $path"
    echo "  expected $want"
    echo "  got      $got"
    exit 1
  fi
  echo "  ok  $path"
}

echo "=== NEW FILES ==="
write_file 'docs/Paper_Skeleton.md' '427f4e2a27b748b57caed3a1043fc19ea15d92b92e0ad5ddc8ea37f94868f2ee' <<'B64EOF'
